Built this against the RN cross-platform rules: 48dp/44pt minimum touch targets (I use a single 48 floor, which clears both), native `Alert` for the destructive confirmation (acts as a `UIAlertController` alert on iOS and an `AlertDialog` on Android — each platform's own "two action max, destructive style separated from Cancel" pattern), `Pressable` with `android_ripple` for native-feeling press feedback per platform, light/dark aware colors, and `marginStart/marginEnd` instead of left/right so the row layout mirrors correctly in RTL.

```tsx
// AccountSettingsScreen.tsx
import React, { useMemo, useState } from 'react';
import {
  View,
  Text,
  Image,
  ScrollView,
  Pressable,
  Switch,
  Alert,
  StyleSheet,
  Platform,
  useColorScheme,
} from 'react-native';

type ThemeColors = {
  background: string;
  surface: string;
  label: string;
  secondaryLabel: string;
  separator: string;
  tint: string;
  destructive: string;
  ripple: string;
};

const LIGHT: ThemeColors = {
  background: '#F2F2F7',
  surface: '#FFFFFF',
  label: '#000000',
  secondaryLabel: '#6C6C70',
  separator: '#E5E5EA',
  tint: '#007AFF',
  destructive: '#FF3B30',
  ripple: 'rgba(0,0,0,0.06)',
};

const DARK: ThemeColors = {
  background: '#000000',
  surface: '#1C1C1E',
  label: '#FFFFFF',
  secondaryLabel: '#9B9B9F',
  separator: '#38383A',
  tint: '#0A84FF',
  destructive: '#FF453A',
  ripple: 'rgba(255,255,255,0.12)',
};

// 44pt is the iOS floor, 48dp is the Android floor — 48 clears both.
const MIN_TARGET = 48;

export type AccountUser = {
  name: string;
  email: string;
  avatarUri?: string;
};

export type AccountSettingsScreenProps = {
  user: AccountUser;
  notificationsEnabled: boolean;
  onEditProfile: () => void;
  onChangePassword: () => void;
  onTwoFactorAuth: () => void;
  onNotificationsChange: (enabled: boolean) => void;
  onAppearance: () => void;
  onLanguage: () => void;
  onHelpCenter: () => void;
  onContactUs: () => void;
  onPrivacyPolicy: () => void;
  onTermsOfService: () => void;
  onLogOut: () => void;
  onDeleteAccount: () => void;
};

export default function AccountSettingsScreen(props: AccountSettingsScreenProps) {
  const scheme = useColorScheme();
  const colors = scheme === 'dark' ? DARK : LIGHT;
  const [notifications, setNotifications] = useState(props.notificationsEnabled);

  const handleToggleNotifications = (value: boolean) => {
    setNotifications(value);
    props.onNotificationsChange(value);
  };

  const confirmLogOut = () => {
    Alert.alert('Log out?', "You'll need to sign in again to use the app.", [
      { text: 'Cancel', style: 'cancel' },
      { text: 'Log Out', style: 'destructive', onPress: props.onLogOut },
    ]);
  };

  const confirmDeleteAccount = () => {
    Alert.alert(
      'Delete account?',
      'This permanently deletes your account, profile and all associated data. This cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        { text: 'Delete', style: 'destructive', onPress: props.onDeleteAccount },
      ],
      { cancelable: true }
    );
  };

  return (
    <ScrollView
      style={[styles.screen, { backgroundColor: colors.background }]}
      contentContainerStyle={styles.content}
      contentInsetAdjustmentBehavior="automatic"
    >
      <Section colors={colors}>
        <ProfileRow
          colors={colors}
          name={props.user.name}
          email={props.user.email}
          avatarUri={props.user.avatarUri}
          onPress={props.onEditProfile}
          isLast
        />
      </Section>

      <SectionHeader colors={colors} title="Preferences" />
      <Section colors={colors}>
        <SettingsRow
          colors={colors}
          label="Notifications"
          rightElement={
            <Switch
              value={notifications}
              onValueChange={handleToggleNotifications}
              trackColor={{ true: colors.tint }}
              accessibilityLabel="Notifications"
            />
          }
        />
        <SettingsRow colors={colors} label="Appearance" value="System" onPress={props.onAppearance} showChevron />
        <SettingsRow colors={colors} label="Language" value="English" onPress={props.onLanguage} showChevron isLast />
      </Section>

      <SectionHeader colors={colors} title="Security" />
      <Section colors={colors}>
        <SettingsRow colors={colors} label="Change Password" onPress={props.onChangePassword} showChevron />
        <SettingsRow
          colors={colors}
          label="Two-Factor Authentication"
          onPress={props.onTwoFactorAuth}
          showChevron
          isLast
        />
      </Section>

      <SectionHeader colors={colors} title="Support" />
      <Section colors={colors}>
        <SettingsRow colors={colors} label="Help Center" onPress={props.onHelpCenter} showChevron />
        <SettingsRow colors={colors} label="Contact Us" onPress={props.onContactUs} showChevron />
        <SettingsRow colors={colors} label="Privacy Policy" onPress={props.onPrivacyPolicy} showChevron />
        <SettingsRow colors={colors} label="Terms of Service" onPress={props.onTermsOfService} showChevron isLast />
      </Section>

      <Section colors={colors}>
        <SettingsRow colors={colors} label="Log Out" onPress={confirmLogOut} centered isLast />
      </Section>

      <Section colors={colors}>
        <SettingsRow
          colors={colors}
          label="Delete Account"
          onPress={confirmDeleteAccount}
          destructive
          centered
          isLast
          accessibilityHint="Permanently deletes your account. This cannot be undone."
        />
      </Section>
    </ScrollView>
  );
}

type ProfileRowProps = {
  colors: ThemeColors;
  name: string;
  email: string;
  avatarUri?: string;
  onPress: () => void;
  isLast?: boolean;
};

function ProfileRow({ colors, name, email, avatarUri, onPress, isLast }: ProfileRowProps) {
  const initials = useMemo(() => getInitials(name), [name]);

  return (
    <Pressable
      onPress={onPress}
      android_ripple={{ color: colors.ripple }}
      accessibilityRole="button"
      accessibilityLabel={`Edit profile, ${name}`}
      style={({ pressed }) => [
        styles.row,
        styles.profileRow,
        !isLast && { borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: colors.separator },
        Platform.OS === 'ios' && pressed && { backgroundColor: colors.ripple },
      ]}
    >
      {avatarUri ? (
        <Image source={{ uri: avatarUri }} style={styles.avatar} />
      ) : (
        <View style={[styles.avatar, styles.avatarFallback, { backgroundColor: colors.tint }]}>
          <Text style={styles.avatarInitials}>{initials}</Text>
        </View>
      )}
      <View style={styles.profileText}>
        <Text style={[styles.profileName, { color: colors.label }]} numberOfLines={1}>
          {name}
        </Text>
        <Text style={[styles.profileEmail, { color: colors.secondaryLabel }]} numberOfLines={1}>
          {email}
        </Text>
      </View>
      <Chevron color={colors.secondaryLabel} />
    </Pressable>
  );
}

type SettingsRowProps = {
  colors: ThemeColors;
  label: string;
  value?: string;
  onPress?: () => void;
  rightElement?: React.ReactNode;
  destructive?: boolean;
  showChevron?: boolean;
  centered?: boolean;
  isLast?: boolean;
  accessibilityHint?: string;
};

function SettingsRow({
  colors,
  label,
  value,
  onPress,
  rightElement,
  destructive,
  showChevron,
  centered,
  isLast,
  accessibilityHint,
}: SettingsRowProps) {
  const textColor = destructive ? colors.destructive : colors.label;

  const content = (
    <View
      style={[
        styles.row,
        centered && styles.rowCentered,
        !isLast && { borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: colors.separator },
      ]}
    >
      <Text style={[styles.rowLabel, { color: textColor }, centered && styles.rowLabelCentered]}>{label}</Text>
      {value && !centered ? <Text style={[styles.rowValue, { color: colors.secondaryLabel }]}>{value}</Text> : null}
      {showChevron && !centered ? <Chevron color={colors.secondaryLabel} /> : null}
      {rightElement}
    </View>
  );

  if (!onPress) {
    return content;
  }

  return (
    <Pressable
      onPress={onPress}
      android_ripple={{ color: colors.ripple }}
      accessibilityRole="button"
      accessibilityLabel={label}
      accessibilityHint={accessibilityHint}
      style={({ pressed }) => [Platform.OS === 'ios' && pressed && { backgroundColor: colors.ripple }]}
    >
      {content}
    </Pressable>
  );
}

function Section({ colors, children }: { colors: ThemeColors; children: React.ReactNode }) {
  return <View style={[styles.section, { backgroundColor: colors.surface }]}>{children}</View>;
}

function SectionHeader({ colors, title }: { colors: ThemeColors; title: string }) {
  return <Text style={[styles.sectionHeader, { color: colors.secondaryLabel }]}>{title}</Text>;
}

function Chevron({ color }: { color: string }) {
  return <Text style={[styles.chevron, { color }]}>›</Text>;
}

function getInitials(name: string): string {
  return name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('');
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
  },
  content: {
    paddingVertical: 16,
    paddingBottom: 48,
  },
  row: {
    minHeight: MIN_TARGET,
    paddingHorizontal: 16,
    paddingVertical: 12,
    flexDirection: 'row',
    alignItems: 'center',
  },
  rowCentered: {
    justifyContent: 'center',
  },
  rowLabel: {
    flex: 1,
    fontSize: 16,
  },
  rowLabelCentered: {
    flex: 0,
    fontWeight: '600',
  },
  rowValue: {
    fontSize: 16,
    marginEnd: 6,
  },
  profileRow: {
    paddingVertical: 12,
  },
  profileText: {
    flex: 1,
    marginStart: 12,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
  },
  profileEmail: {
    fontSize: 14,
    marginTop: 2,
  },
  avatar: {
    width: 56,
    height: 56,
    borderRadius: 28,
  },
  avatarFallback: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  avatarInitials: {
    color: '#FFFFFF',
    fontSize: 20,
    fontWeight: '600',
  },
  sectionHeader: {
    marginTop: 24,
    marginBottom: 8,
    marginHorizontal: 20,
    fontSize: 13,
    fontWeight: '600',
  },
  section: {
    marginHorizontal: 16,
    marginBottom: 8,
    borderRadius: 10,
    overflow: 'hidden',
  },
  chevron: {
    fontSize: 20,
    marginStart: 4,
  },
});
```

Example usage:

```tsx
<AccountSettingsScreen
  user={{ name: 'Jordan Rivera', email: 'jordan@example.com', avatarUri: undefined }}
  notificationsEnabled={true}
  onEditProfile={() => navigation.navigate('EditProfile')}
  onChangePassword={() => navigation.navigate('ChangePassword')}
  onTwoFactorAuth={() => navigation.navigate('TwoFactorAuth')}
  onNotificationsChange={(enabled) => api.setNotifications(enabled)}
  onAppearance={() => navigation.navigate('Appearance')}
  onLanguage={() => navigation.navigate('Language')}
  onHelpCenter={() => navigation.navigate('HelpCenter')}
  onContactUs={() => navigation.navigate('ContactUs')}
  onPrivacyPolicy={() => navigation.navigate('PrivacyPolicy')}
  onTermsOfService={() => navigation.navigate('TermsOfService')}
  onLogOut={() => auth.signOut()}
  onDeleteAccount={() => api.deleteAccount()}
/>
```

Notes on a couple of calls I made, in case you want to diverge:
- Delete/Log Out use a plain `Alert` rather than an iOS action sheet — matches how Apple's own Settings app confirms account deletion, and keeps one code path for both platforms instead of branching on `Platform.OS`.
- Colors are a shared semantic palette rather than separate Material/Cupertino systems — reasonable for a single cross-platform visual language, but if you want each OS to feel fully native, swap in platform-specific tokens (Material 3 surface-container roles for Android, system background/label colors for iOS) instead of this shared set.
